class Logo(rai.Compo):
    def _make(self,
             Logo = 'TIFUUN_icon'
             ):

        String_lib = Logostring.get(Logo)
        
        for item in range(len(String_lib)):
            test = String_lib[item]

            cleaned_points = [tuple(map(int, point.strip('()').split(','))) for point in test.split('),')]
            object = rai.CustomPoly(
                cleaned_points
                ).proxy()
    
            "Placing the objects"
            self.subcompos[f"Object_{item}"] = object
        
        ## Determine height of the logo
        height = self.bbox.top_mid[1] - self.bbox.bot_mid[1]

        ### Scale all components such that the vertical length in normalized to 100
        for item in range(len(String_lib)):
            self.subcompos[f"Object_{item}"] = self.subcompos[f"Object_{item}"].proxy().scale(100/height)

